import pandas as pd
df=pd.read_excel('programme_monthly_spend.xlsx', sheet_name='Monthly Spend', header=None)
rows=df.iloc[4:17,4:10]
def to_num(x):
    if pd.isna(x):
        return 0
    if isinstance(x,str):
        s=x.strip()
        if s in ['','-','–','—']:
            return 0
        try:
            return float(s.replace(',',''))
        except:
            return 0
    try:
        return float(x)
    except:
        return 0
total=0
for r in rows.values:
    for v in r:
        total+=to_num(v)
print(total)
